SELECT 'Updating static data table util.datahub_load_control';

-- 1: Define table variable
CREATE OR REPLACE temporary TABLE UTIL.tmp_DATAHUB_LOAD_CONTROL
(
	DATAHUB_LOAD_CONTROL_HKEY VARCHAR(32), -- NULLABLE on purpose here, to make the insert statements below cleaner
    IS_ACTIVE BOOLEAN NOT NULL,
    DATA_DOMAIN_NAME VARCHAR NOT NULL COMMENT 'CLAIMS, MEMBER, PROVIDER, etc.',
    DATA_SOURCE_NAME VARCHAR NOT NULL COMMENT 'Skygen, MC400Dnt, MC400Upm, etc.',
    TYPE_CODE VARCHAR NOT NULL COMMENT 'HUB, SAT, LNK, REF',
    PROCEDURE_NAME VARCHAR NOT NULL COMMENT 'Example: HUBDATA.SPU_LOAD_HUB_CLAIM',
    SOURCE_VIEW_NAME VARCHAR NOT NULL COMMENT 'Example: STAGEDATA.HUB_CLAIM_NVA_SELECT_VW',
	RUN_ORDER_NBR NUMBER COMMENT 'Applies only to LKP tables where a specific run order is required - Example: 1',
    CONSTRAINT PK_DATAHUB_LOAD_CONTROL PRIMARY KEY (DATA_DOMAIN_NAME, DATA_SOURCE_NAME, TYPE_CODE, PROCEDURE_NAME, SOURCE_VIEW_NAME),
    CONSTRAINT UK_DATAHUB_LOAD_CONTROL UNIQUE (DATA_DOMAIN_NAME, DATA_SOURCE_NAME, TYPE_CODE, PROCEDURE_NAME, SOURCE_VIEW_NAME)
)
;
