--Set the HKEY for all the records in the temp table.
UPDATE UTIL.tmp_DATAHUB_LOAD_CONTROL
SET DATAHUB_LOAD_CONTROL_HKEY = UTIL.FXN_ARRAY_HASH([DATA_DOMAIN_NAME, DATA_SOURCE_NAME, TYPE_CODE, PROCEDURE_NAME, SOURCE_VIEW_NAME, RUN_ORDER_NBR])
;

--Use a minus query to find any diffs and update or insert as needed	 
MERGE INTO UTIL.DATAHUB_LOAD_CONTROL AS TGT
USING (SELECT DATAHUB_LOAD_CONTROL_HKEY, IS_ACTIVE, DATA_DOMAIN_NAME, DATA_SOURCE_NAME, TYPE_CODE, PROCEDURE_NAME, SOURCE_VIEW_NAME, RUN_ORDER_NBR
	FROM  UTIL.tmp_DATAHUB_LOAD_CONTROL
	MINUS 
	SELECT DATAHUB_LOAD_CONTROL_HKEY, IS_ACTIVE, DATA_DOMAIN_NAME, DATA_SOURCE_NAME, TYPE_CODE, PROCEDURE_NAME, SOURCE_VIEW_NAME, RUN_ORDER_NBR
	FROM UTIL.DATAHUB_LOAD_CONTROL
	) AS SRC

ON (TGT.DATAHUB_LOAD_CONTROL_HKEY = SRC.DATAHUB_LOAD_CONTROL_HKEY)

WHEN MATCHED 
THEN UPDATE
	SET 
	TGT.IS_ACTIVE = SRC.IS_ACTIVE
	,TGT.LAST_UPDATED_DATETIME = CURRENT_TIMESTAMP()
WHEN NOT MATCHED 
THEN INSERT
	(
		DATAHUB_LOAD_CONTROL_HKEY
		,INSERT_DATETIME
		,LAST_UPDATED_DATETIME
		,IS_ACTIVE
		,DATA_DOMAIN_NAME
		,DATA_SOURCE_NAME
		,TYPE_CODE
		,PROCEDURE_NAME
		,SOURCE_VIEW_NAME
		,RUN_ORDER_NBR
	)
VALUES
	(
		src.DATAHUB_LOAD_CONTROL_HKEY
		,CURRENT_TIMESTAMP()
		,CURRENT_TIMESTAMP()
		,src.IS_ACTIVE
		,src.DATA_DOMAIN_NAME
		,src.DATA_SOURCE_NAME
		,src.TYPE_CODE
		,src.PROCEDURE_NAME
		,src.SOURCE_VIEW_NAME
		,src.RUN_ORDER_NBR
	)
;
	
--Flip the minus and delete from the target
DELETE FROM UTIL.DATAHUB_LOAD_CONTROL TGT
USING
(SELECT DATAHUB_LOAD_CONTROL_HKEY
	FROM UTIL.DATAHUB_LOAD_CONTROL
	MINUS 
	SELECT DATAHUB_LOAD_CONTROL_HKEY
	FROM UTIL.tmp_DATAHUB_LOAD_CONTROL
	) SRC
WHERE TGT.DATAHUB_LOAD_CONTROL_HKEY = SRC.DATAHUB_LOAD_CONTROL_HKEY
;

SELECT 'Finished updating static data table util.datahub_load_control';